<?php require_once __DIR__.'/../../includes/admin-check.php';$rows=$pdo->query('SELECT s.id,s.deskripsi,k.kode,k.nama FROM solusi s JOIN kerusakan k ON k.id=s.kerusakan_id ORDER BY s.id DESC')->fetchAll();$pageTitle='Solusi';require __DIR__.'/../../includes/header.php';?><div class="heading"><h1>Solusi</h1><a class="button" href="tambah.php">Tambah solusi</a></div><table><tr><th>Kerusakan</th><th>Solusi</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['kode'].' - '.$r['nama'])?></td><td><?=e($r['deskripsi'])?></td><td><a href="edit.php?id=<?=$r['id']?>">Edit</a><form class="inline" method="post" action="hapus.php" onsubmit="return confirm('Hapus solusi?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button>Hapus</button></form></td></tr><?php endforeach?></table><?php require __DIR__.'/../../includes/footer.php';?>